ALTER TABLE public.duels ADD COLUMN IF NOT EXISTS selected_categories jsonb NOT NULL DEFAULT '["logic","pattern","speed","attention","word","arcade"]'::jsonb; ALTER TABLE public.duels ADD COLUMN IF NOT EXISTS tournament_history jsonb NOT NULL DEFAULT '[]'::jsonb; ALTER TABLE public.duels ADD COLUMN IF NOT EXISTS disbanded_at timestamptz; UPDATE public.duels SET selected_categories = (SELECT jsonb_agg(category ORDER BY priority) FROM (SELECT 'logic' category, 1 priority UNION ALL SELECT 'pattern',2 UNION ALL SELECT 'speed',3 UNION ALL SELECT 'attention',4 UNION ALL SELECT 'word',5 UNION ALL SELECT 'number',6 WHERE add_maths UNION ALL SELECT 'memory',7 WHERE add_memory UNION ALL SELECT 'arcade',8 WHERE add_arcade) chosen) WHERE selected_categories = '["logic","pattern","speed","attention","word","arcade"]'::jsonb AND (add_maths OR add_memory OR NOT add_arcade); CREATE OR REPLACE FUNCTION public.restart_duel_room(p_room_id uuid, p_host_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_room public.duels%ROWTYPE; v_winner jsonb; BEGIN SELECT * INTO v_room FROM public.duels WHERE id = p_room_id FOR UPDATE; IF NOT FOUND OR v_room.status <> 'finished' OR v_room.host_user_id <> p_host_id OR v_room.disbanded_at IS NOT NULL THEN RETURN false; END IF; SELECT jsonb_build_object('winner', display_name, 'date', now(), 'score', points, 'round_order', v_room.round_order) INTO v_winner FROM (SELECT p.display_name, coalesce(sum(r.score),0) points FROM public.duel_players p LEFT JOIN public.round_results r ON r.duel_id = p_room_id AND r.player_slot = p.player_slot WHERE p.duel_id = p_room_id AND p.status <> 'left' GROUP BY p.id ORDER BY points DESC, p.player_slot LIMIT 1) ranking; DELETE FROM public.round_results WHERE duel_id = p_room_id; DELETE FROM public.duel_secrets WHERE duel_id = p_room_id; DELETE FROM public.duel_players WHERE duel_id = p_room_id AND status = 'left'; UPDATE public.duel_players SET status = 'active', ready_round = 0, intro_ready_round = 0 WHERE duel_id = p_room_id; UPDATE public.duels SET status = 'waiting', round_order = '[]'::jsonb, puzzles_public = '[]'::jsonb, current_round = 0, phase = 'intro', phase_started_at = NULL, round_started_at = NULL, tournament_history = tournament_history || coalesce(jsonb_build_array(v_winner),'[]'::jsonb) WHERE id = p_room_id; RETURN true; END; $$; REVOKE ALL ON FUNCTION public.restart_duel_room(uuid,uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.restart_duel_room(uuid,uuid) TO service_role; CREATE OR REPLACE FUNCTION public.disband_stale_room(p_room_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN UPDATE public.duels d SET disbanded_at = now(), status = 'finished' FROM public.duel_players p WHERE d.id = p_room_id AND d.status = 'waiting' AND d.disbanded_at IS NULL AND p.duel_id = d.id AND p.user_id = d.host_user_id AND p.last_seen_at < now() - interval '2 minutes'; RETURN FOUND; END; $$; REVOKE ALL ON FUNCTION public.disband_stale_room(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.disband_stale_room(uuid) TO service_role;